-- =====================================================================
-- F1 SIM — invite codes, enforced and generated by the system.
-- Every new account needs a valid invite code, apart from the very first
-- (the Administrator's). With no code issued, new accounts are closed.
-- Codes are made by the database: 10 characters from letters and digits
-- that can't be mistaken for one another (no O, 0, I or 1). Only a
-- one-way hash is kept; the code itself is shown to the Administrator
-- once, when it's generated. Signing in to an existing account is not
-- affected.
-- =====================================================================

create or replace function public.check_invite() returns trigger
language plpgsql security definer set search_path = public, private, extensions as $$
declare h text; given text := upper(regexp_replace(coalesce(new.raw_user_meta_data ->> 'invite', ''), '\s', '', 'g'));
begin
    if exists (select 1 from public.members) then
        select value into h from private.config where key = 'invite_hash';
        if h is null then raise exception 'invite_code_required' using errcode = '42501'; end if;
        if given = '' or extensions.crypt(given, h) <> h then raise exception 'invite_code_invalid' using errcode = '42501'; end if;
    end if;
    new.raw_user_meta_data := coalesce(new.raw_user_meta_data, '{}'::jsonb) - 'invite';
    return new;
end $$;

-- Is an invite code needed? Yes, once the Administrator's account exists.
create or replace function public.invite_required() returns boolean
language sql stable security definer set search_path = public, private as $$
    select exists (select 1 from public.members)
$$;

-- Is a code issued right now? (If not, new accounts are closed.)
create or replace function public.invite_open() returns boolean
language sql stable security definer set search_path = public, private as $$
    select exists (select 1 from private.config where key = 'invite_hash')
$$;

-- The Administrator generates a code: returned once, stored only as a hash.
create or replace function public.admin_generate_invite_code() returns text
language plpgsql volatile security definer set search_path = public, private, extensions as $$
declare alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; b bytea := extensions.gen_random_bytes(10); code text := ''; i int;
begin
    if coalesce(public.my_role(), '') <> 'owner' then raise exception 'Only the Administrator sets the invite code' using errcode = '42501'; end if;
    -- 32 characters, so each random byte maps evenly onto one of them.
    for i in 0..9 loop code := code || substr(alphabet, (get_byte(b, i) % 32) + 1, 1); end loop;
    insert into private.config (key, value) values ('invite_hash', extensions.crypt(code, extensions.gen_salt('bf')))
        on conflict (key) do update set value = excluded.value;
    insert into private.config (key, value) values ('invite_at', now()::text)
        on conflict (key) do update set value = excluded.value;
    return code;
end $$;

-- Closing sign-ups: an empty code removes the current one. Codes can no longer be typed in by hand.
create or replace function public.admin_set_invite_code(p_code text) returns void
language plpgsql security definer set search_path = public, private, extensions as $$
begin
    if coalesce(public.my_role(), '') <> 'owner' then raise exception 'Only the Administrator sets the invite code' using errcode = '42501'; end if;
    if coalesce(trim(p_code), '') <> '' then raise exception 'Invite codes are generated by the system: use Generate a new code' using errcode = '22023'; end if;
    delete from private.config where key in ('invite_hash', 'invite_at');
end $$;

-- What the Administrator sees: whether a code is issued, and when it was made.
create or replace function public.admin_invite_status() returns jsonb
language plpgsql stable security definer set search_path = public, private as $$
begin
    if coalesce(public.my_role(), '') <> 'owner' then raise exception 'Only the Administrator sees the invite code' using errcode = '42501'; end if;
    return jsonb_build_object('issued', exists (select 1 from private.config where key = 'invite_hash'),
                              'at', (select value from private.config where key = 'invite_at'));
end $$;

revoke execute on function public.admin_generate_invite_code(), public.admin_invite_status() from public, anon;
grant execute on function public.admin_generate_invite_code(), public.admin_invite_status() to authenticated;
grant execute on function public.invite_required(), public.invite_open() to anon, authenticated;
